const crypto = require('crypto');

const body = $input.first().json.body ?? {};
const email = (body.email ?? '').trim();
const password = (body.password ?? '').trim();

// Kimlik doğrulama — AUTH_EMAIL ve AUTH_PASSWORD n8n env var'dan gelir
if (!email || !password) {
  throw new Error('Email ve şifre zorunlu');
}
if (email !== $env.AUTH_EMAIL || password !== $env.AUTH_PASSWORD) {
  throw new Error('Geçersiz kimlik bilgileri');
}

// HS256 JWT oluştur
const b64u = (obj) =>
  Buffer.from(JSON.stringify(obj))
    .toString('base64')
    .replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');

const now = Math.floor(Date.now() / 1000);
const exp = now + 28800; // 8 saat

const header  = b64u({ alg: 'HS256', typ: 'JWT' });
const payload = b64u({ sub: email, iat: now, exp });
const sig = crypto
  .createHmac('sha256', $env.JWT_SECRET)
  .update(`${header}.${payload}`)
  .digest('base64')
  .replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');

const token = `${header}.${payload}.${sig}`;

return [{ json: { token, expires_at: new Date(exp * 1000).toISOString() } }];
